namespace red_crc32_step64b {
void crc32_step64b_iss(const uint32_t in[17], uint32_t out[17])
{
    // Read all 17 input words before writing any output (spec: overlap-safe).
    uint32_t crc = in[0];
    uint32_t w[16];
    for (int i = 0; i < 16; ++i)
        w[i] = in[1 + i];

    for (int k = 0; k < 64; ++k) {
        uint32_t byte = (w[k / 4] >> (8u * (uint32_t)(k % 4))) & 0xFFu;
        uint32_t x = crc ^ byte;
        for (int b = 0; b < 8; ++b) {
            uint32_t m = 0u - (x & 1u);
            x = (x >> 1) ^ (0xEDB88320u & m);
        }
        crc = x;
    }

    out[0] = crc;
    for (int i = 1; i < 17; ++i)
        out[i] = 0u;
}
}



